using System.Buffers.Text;
using System.Security.Cryptography;
using System.Text;

namespace SendFiles.Core.Devices;

/// <summary>
/// Long-lived device key: <c>sf1.&lt;deviceId&gt;.&lt;secret&gt;</c> (base64url, 16 and 32 random bytes).
/// Generated by the PC (the phone has no <c>crypto.subtle</c> over HTTP); only SHA-256 of the secret is stored.
/// 256 bits of entropy make a slow KDF unnecessary.
/// </summary>
public static class DeviceKey
{
    public const string Prefix = "sf1";
    private const int IdBytes = 16;
    private const int SecretBytes = 32;

    public static (string DeviceId, string Secret, string Key) Generate()
    {
        var id = Base64Url.EncodeToString(RandomNumberGenerator.GetBytes(IdBytes));
        var secret = Base64Url.EncodeToString(RandomNumberGenerator.GetBytes(SecretBytes));
        return (id, secret, $"{Prefix}.{id}.{secret}");
    }

    public static bool TryParse(string? value, out string deviceId, out string secret)
    {
        deviceId = secret = string.Empty;
        if (string.IsNullOrEmpty(value) || value.Length > 128)
        {
            return false;
        }

        var parts = value.Split('.');
        if (parts.Length != 3 || parts[0] != Prefix
            || !IsBase64Url(parts[1], IdBytes) || !IsBase64Url(parts[2], SecretBytes))
        {
            return false;
        }

        deviceId = parts[1];
        secret = parts[2];
        return true;
    }

    public static string Hash(string secret) =>
        Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(secret)));

    public static bool Verify(string secret, string expectedHash)
    {
        Span<byte> actual = stackalloc byte[32];
        SHA256.HashData(Encoding.UTF8.GetBytes(secret), actual);
        Span<byte> expected = stackalloc byte[32];
        return Convert.TryFromBase64String(expectedHash, expected, out var written)
            && written == 32
            && CryptographicOperations.FixedTimeEquals(actual, expected);
    }

    /// <summary>Random base64url token for one-time QR tokens, tickets and request secrets.</summary>
    public static string RandomToken(int bytes = 32) => Base64Url.EncodeToString(RandomNumberGenerator.GetBytes(bytes));

    private static bool IsBase64Url(string value, int byteCount) =>
        value.Length == Base64Url.GetEncodedLength(byteCount) && Base64Url.IsValid(value, out var decoded) && decoded == byteCount;
}
